/* Source: shared/lib/ui.js; formatDialledNumber. Generated by standalone-build.mjs. */
function formatDialledNumber(value,dial){
    const digits=String(value || '').replace(/\D/g,'');
    if(dial==='66') return formatThaiPhone(digits);
    if(!digits) return '';
    return digits.replace(/(\d{1,3})(\d{1,3})?(\d{1,4})?/, (m,a,b,c) =>
      [a,b,c].filter(Boolean).join(' ')).trim();
  }

/* Source: shared/lib/identity.js; phoneFieldDial. Generated by standalone-build.mjs. */
function phoneFieldDial(field){
    return String(field?.querySelector('[data-phone-dial]')?.textContent || '+66').replace('+','');
  }
